const outlineData = {"chapters":[{"chapterNumber":0,"title":"Preface","sections":[{"level":1,"heading":"Preface","bibleReferences":[],"subsections":[]}]},{"chapterNumber":1,"title":"Chapter 1: Biblical Theology and Systematic Theology in Covenant Theology","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Covenant theology (CT) explains God's single, unified redemptive purpose across all history","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Studying it requires humility (God's ways are unsearchable) balanced with diligence","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Four methodological challenges will structure the rest of the chapter","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. Scope and Simplicity","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: CT's scope is the whole of Scripture, worked at both the macro and micro levels","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Breadth of coverage","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Spans the whole of Scripture, from creation to consummation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Works at both the macro (big-picture) and micro (fine-detail) levels","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. What that breadth requires of the interpreter","bibleReferences":[],"subsections":[{"level":5,"heading":"1. CT must explain the theological weight of redemptive history, not just narrate it","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Large-scale conclusions must rest on thoroughly examined details, not shortcuts","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Conclusion \u2014 what that breadth rules out","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Oversimplified summaries that lose the connecting threads between parts","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Treating the \u201cbig picture\u201d as sufficient without the smaller supporting lines","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. Creation, Covenant, and Consequences","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: covenants are additions on top of nature, not part of it","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The basic distinction","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Creation and its natural order are built into the world by nature","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Covenants are additions on top of nature, not part of it","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. What follows for the Creator-creature relationship","bibleReferences":[],"subsections":[{"level":5,"heading":"1. By nature, creatures owe God obedience; God owes them nothing extra in return","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Covenants exist only because God freely grants benefits beyond what nature requires","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Two parallel distinctions this generates","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Natural law (known by nature) vs. positive law (added by revelation)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Natural worship (owed by nature) vs. instituted worship (regulated only by God's command)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iv. Consequence \u2014 the resulting limit on inference","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Because covenants aren't natural, no covenant's details can be assumed to carry over to another by logical necessity","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. A feature in one covenant (a seal, a blood ritual, family inclusion) doesn't automatically transfer to a different covenant","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"v. Conclusion \u2014 what this does not mean","bibleReferences":[],"subsections":[{"level":5,"heading":"1. It doesn't prevent comparing Scripture with Scripture on the same covenant","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. It doesn't require the word \u201ccovenant\u201d to appear explicitly for a covenant to be present","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"3. The Law and the Gospel","bibleReferences":[],"subsections":[{"level":3,"heading":"a. First sense \u2014 the doctrinal sense","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Law and gospel are opposite paths to righteousness \u2014 one earned by works, one received by faith","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. This contrast anchored the Reformation's break from Rome's blending of faith and works","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Second sense \u2014 the historical sense","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Law and gospel also serve as broad labels for the Old and New Testament eras","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Revelation grows clearer over time, but the underlying way of salvation doesn't change","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Conclusion \u2014 holding both senses together","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Old and New Testament believers were saved the same way, by grace through faith","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. That underlying continuity is not evidence that the Abrahamic, Mosaic, and Davidic covenants are simply identical to the New Covenant of grace","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. A sound CT preserves both the continuity in salvation and the real differences between the covenants themselves","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. History and Mystery","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion \u2014 what \u201cmystery\u201d means for Paul","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The full inclusion of the nations through Christ was revealed gradually and partially, not concealed forever","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. It reaches full clarity only through Christ's death, resurrection, and Pentecost","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Proof \u2014 evidence that it stayed partially hidden","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Even the disciples still expected a restored Jewish kingdom after the resurrection","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Full comprehension came only with a greater outpouring of the Spirit","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Conclusion \u2014 what this requires of CT's method","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The Old Testament's witness to Christ must be allowed to stay veiled the way Scripture itself presents it","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. New Testament clarity should not be read backward into earlier stages of revelation, since that would erase the very mystery Scripture describes","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The four considerations \u2014 scope, creation/covenant, law/gospel, mystery \u2014 form the necessary starting framework for the rest of the study","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Given the size and difficulty of the subject, the fitting response is humility and worship, not confidence in having mastered it","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":2,"title":"Chapter 2: Typology","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Typology is a core interpretive tool for reading Scripture in general and for covenant theology in particular","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. The Bible\u2019s covenants and its typological patterns are closely bound together \u2014 tracing one usually means tracing the other","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. What is Typology?","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Basic definition","bibleReferences":[],"subsections":[{"level":4,"heading":"i. A divinely intended correspondence between an earlier person, event, or institution and a later, greater fulfillment","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Different theologians phrase this differently, but generally agree on the core idea","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Core features of a type (following Beale\u2019s definition)","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Analogical correspondence \u2014 a real likeness between the type and its fulfillment","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Historicity \u2014 the type is a real historical person, event, or institution, not a literary device","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. A pointing-forward function, understood clearly only in hindsight (\u201cretrospection\u201d)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Escalation \u2014 the fulfillment surpasses the type","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: a real heightening or intensification occurs","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: it is not a mere repetition of the same thing at the same level","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. How later Scripture unpacks earlier Scripture","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Old Testament passages carry a genuine but incomplete meaning at the time they were written","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: the human authors truly understood what they wrote","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: their understanding was not exhaustive","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Later revelation, especially the New Testament, unfolds and expands that meaning without contradicting it","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Where types can be found","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Not limited to places where Scripture explicitly uses the word \u201ctype\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Interpreters may identify further typological connections, provided they stay anchored in Scripture\u2019s own pattern of usage rather than in speculation","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"e. What keeps this from becoming arbitrary","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Types are divinely ordained and preordained in advance, not simply noticed after the fact","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Christ must be the center of any legitimate typological reading","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: a type must ultimately point to Christ, His covenant, and His kingdom","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: a \u201ctype\u201d without Christ in view is not functioning as typology at all","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. The Relation between a Type and its Antitype","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Theologians often agree on typology\u2019s definition in the abstract but disagree sharply once they start applying it","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. This section works out the relationship more precisely","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Types reveal something greater, and other, than themselves.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Typology is not a sliding scale from a duller version to a brighter version of the same thing","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Scripture consistently uses paired contrasting language","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Shadow vs. substance","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Picture vs. reality","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Supporting examples show the type is not itself the fulfillment","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The wilderness bread (John 6:32\u201333, 58)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: it pointed to Christ, the \u201ctrue bread from heaven\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: it was not itself a lesser version of Christ","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. The wilderness rock (1 Corinthians 10:4)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: it portrayed Christ","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: the rock and its water were not actually Christ","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iii. The Mosaic law (Colossians 2:17)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: it looked forward to Christ and His kingdom","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: it was not, in itself, Christ and His kingdom","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iv. The tabernacle and its sacrifices (Hebrews 8:5; 9:23\u201324; 10:1)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: they served as a copy and shadow of heavenly realities","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: the copies could not themselves purify what the true heavenly sacrifice would purify","bibleReferences":[],"subsections":[]}]}]}]},{"level":3,"heading":"b. Types function on two levels.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. The immediate level","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Types had a genuine function and meaning in their own original setting","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Example: animal sacrifices really addressed outward, ceremonial guilt under the Old Covenant","bibleReferences":[],"subsections":[{"level":6,"heading":"1. They dealt with purification of the flesh","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. But could not purify the conscience","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. The pointing-forward level","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The same institution simultaneously anticipated a greater, future fulfillment in Christ","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. This double function let Old Testament believers receive real benefit even from something that was not the final reality","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Contrast \u2014 why this differs from ordinary \u201calready/not yet\u201d language","bibleReferences":[],"subsections":[{"level":5,"heading":"i. New Testament blessings are the same reality experienced partially now and fully later","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Old Testament types worked differently","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: they signified one thing on the surface (an earthly meaning)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: while revealing something else entirely (a greater, heavenly meaning)","bibleReferences":[],"subsections":[]}]}]}]},{"level":3,"heading":"c. Types terminate in their antitypes.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: once the greater reality has come, the type that anticipated it is no longer needed","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Consequence: continuing to rely on the type after the fulfillment has arrived effectively denies that the fulfillment actually happened","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Illustrations offered","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Seeing a friend\u2019s shadow around a corner: you don\u2019t talk to the shadow once the friend himself appears","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. A restaurant menu: once the food has arrived, the picture in the menu is no longer needed","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Types are positive and negative.","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Some types anticipate the fulfillment by resemblance \u2014 a positive picture of what is to come","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Others anticipate it by highlighting their own failure or insufficiency \u2014 a negative contrast with what is to come","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Example: the yearly sacrifices served as a reminder of ongoing guilt (Hebrews 10:3) even while pointing toward a final, lasting remission of sins","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion: either way, the comparison serves the same purpose \u2014 to magnify how much greater the fulfillment is than the type that anticipated it","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. The Application of Typological Principles","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Where theologians agreed","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Reformed theologians broadly agreed the Mosaic covenant had a typical, shadow-like character","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Where they disagreed","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Whether that typical character meant the Old and New Covenants differ merely in degree (an immature form growing into a mature form of the same covenant)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Or whether they differ in actual substance (genuinely different covenants, not just different stages)","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. The two positions summarized","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Burgess\u2019s view","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: the difference between the covenants is one of degree \u2014 from inferior to superior, from less to more","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: not a difference in substance","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Owen\u2019s view (and the Particular Baptists\u2019)","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Positive: the Old and New Covenants differ \u201cas to the essence and substance of them\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: not merely as different administrations of the very same covenant","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Conclusion \u2014 why this dispute matters","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Since a type is genuinely distinct from its antitype, treating the difference as one of \u201csubstance\u201d fits the nature of typology more consistently","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. This is the position followed in this book, aligning with Owen and the Particular Baptists rather than those who saw only a difference of degree","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Small differences in how typology gets applied can lead to very different theological systems down the line","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Getting the underlying principles right is therefore essential before drawing larger conclusions","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":3,"title":"Chapter 3: Covenant and Kingdom","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Two foundational questions need answers before going further: what is a covenant, and what does a covenant do?","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. What is a Covenant?","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion: a covenant involves binding commitments between two parties, secured by threats that guarantee they'll be kept","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Clarification: since God always initiates","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Positive: His covenants are gracious gifts","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Negative: not negotiated deals","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"a. The definition of a covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. The core shape","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Two parties make mutual \u201cI will / you will\u201d commitments","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Different kinds of commitments produce different kinds of covenants","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Why a commitment alone isn't enough","bibleReferences":[],"subsections":[{"level":5,"heading":"i. A bare commitment lacks legal force until sanctions are attached","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Sanctions add the formality that turns a promise into a covenant","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion \u2014 why covenants are gracious, not negotiated","bibleReferences":[],"subsections":[{"level":5,"heading":"i. God imposes the terms; man doesn't get to bargain them","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Even so, every covenant offers real benefits beyond what nature already provides","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"b. Covenant sanctions","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion: covenant-making in the Ancient Near East and in Scripture consistently involves dramatic ritual sanctions","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof \u2014 the pattern","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Animals cut in half","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Oaths invoking curses","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Proof \u2014 examples across Scripture","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Jeremiah 34 (the covenant to free Jewish slaves, later broken)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Psalm 50 (\u201cmade a covenant with me by sacrifice\u201d)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Jonathan and David in 1 Samuel 20 (a self-directed curse without a blood ritual)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"4. Abraham in Genesis 15 (God takes the death-oath upon Himself)","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. Second assertion: a close reading of Hebrews 9:16\u201317 confirms this same sanction-based logic, against the standard translation","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Problem with the ESV's translation","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The ESV reads it as a last will and testament","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Renihan argues this is inadequate and proposes a covenant-ratification reading instead","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Exegetical step 1 \u2014 why \u201ccovenant,\u201d not \u201ctestament,\u201d is the right frame","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Old Testament usage of \u03b4\u03b9\u03b1\u03b8\u03ae\u03ba\u03b7 (covenant) always describes an arrangement between living parties","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: covenants are struck between the living","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: not wills activated only at death","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"2. It would be foreign to biblical usage for the concept of a will to suddenly appear in Hebrews without warning","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iii. Exegetical step 2 \u2014 what must the covenanter do (\u03c6\u03ad\u03c1\u03b5\u03c3\u03b8\u03b1\u03b9)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The Greek verb in question is \u03c6\u03ad\u03c1\u03b5\u03c3\u03b8\u03b1\u03b9","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. The ESV treats it as meaning \u201cto be established,\u201d i.e., death is brought forward as evidence","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Renihan argues it must be read alongside a related word used elsewhere in Hebrews, \u03c0\u03c1\u03bf\u03c3\u03c6\u03ad\u03c1\u03c9, which refers to priestly offerings","bibleReferences":[],"subsections":[]},{"level":6,"heading":"4. Drawing the contrast","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: the covenanter's death is \u201cbrought forward as evidence\u201d or \u201cpledged\u201d (\u03c6\u03ad\u03c1\u03b5\u03c3\u03b8\u03b1\u03b9) \u2014 an oath guaranteeing future participation","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: the covenanter is not himself being sacrificed or offered up (\u03c0\u03c1\u03bf\u03c3\u03c6\u03ad\u03c1\u03c9)","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"5. The idea is that a potential death is sworn as security, not that an actual death has occurred","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iv. Exegetical step 3 \u2014 the prepositional phrase \u1f10\u03c0\u1f76 \u03bd\u03b5\u03ba\u03c1\u03bf\u1fd6\u03c2 (\u201cat death\u201d)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The word \u03bd\u03b5\u03ba\u03c1\u03cc\u03c2 refers to the state of being dead, not the event of dying","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: Hebrews 9:16 uses \u03b8\u03ac\u03bd\u03b1\u03c4\u03bf\u03c2 for the event of dying","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: verse 17 shifts to \u03bd\u03b5\u03ba\u03c1\u03bf\u1fd6\u03c2, which does not carry that meaning","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"2. \u03bd\u03b5\u03ba\u03c1\u03bf\u1fd6\u03c2 is plural (\u201cdead bodies\u201d), not singular","bibleReferences":[],"subsections":[{"level":7,"heading":"A will only requires one body to take effect","bibleReferences":[],"subsections":[]},{"level":7,"heading":"A covenant is consistently associated with multiple bodies or corpses at its inauguration (citing O. Palmer Robertson)","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"3. Conclusion of this step: the phrase should be rendered \u201cby corpses\u201d or \u201cover corpses,\u201d not \u201cat death\u201d","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"v. Exegetical step 4 \u2014 confirmation from Psalm 50:5 in Greek","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The Greek text says covenants (\u03b4\u03b9\u03b1\u03b8\u03ae\u03ba\u03b7) are made \u201cby sacrifice\u201d (\u1f10\u03c0\u1f76 \u03b8\u03c5\u03c3\u03af\u03b1\u03b9\u03c2)","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. This mirrors the same construction used in Hebrews 9:17","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. The parallel supports reading Hebrews as describing covenant ratification by sacrifice","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"vi. Exegetical step 5 \u2014 completing the translation (\u03b2\u03b5\u03b2\u03b1\u03af\u03b1 vs. \u1f30\u03c3\u03c7\u03cd\u03b5\u03b9)","bibleReferences":[],"subsections":[{"level":6,"heading":"1. \u03b2\u03b5\u03b2\u03b1\u03af\u03b1 = \u201cformally established, ratified, valid\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. \u1f30\u03c3\u03c7\u03cd\u03b5\u03b9 = \u201cto be in force, to be strong\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. The logic: a covenant is ratified by corpses precisely so that it will not be in force while the covenanter is alive and could violate it","bibleReferences":[],"subsections":[{"level":7,"heading":"Positive: the threat of death secures the covenant's terms","bibleReferences":[],"subsections":[]},{"level":7,"heading":"Negative: without that threat, the covenant would have no power or force","bibleReferences":[],"subsections":[]}]}]},{"level":5,"heading":"vii. Illustration","bibleReferences":[],"subsections":[{"level":6,"heading":"1. A parking lot with posted fines for disabled spaces is respected; one without posted fines is not","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Summary: \u201cno sanctions, no covenant\u201d","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"viii. Conclusion of this exegetical argument","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The precise form of covenant-making ceremonies varies across Scripture","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. But in every case, some sanction guarantees that the covenantal commitments will be fulfilled","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Without imprecatory oaths or threats, a covenant carries no binding force","bibleReferences":[],"subsections":[]}]}]}]},{"level":3,"heading":"c. The matter and form of a covenant","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Definition \u2014 the two categories","bibleReferences":[],"subsections":[{"level":5,"heading":"i. \u201cMatter\u201d = the actual content of the commitments","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Law, or","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Promise","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. \u201cForm\u201d = the point at which sanctions formally ratify those commitments","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Application \u2014 how this produces two kinds of covenants","bibleReferences":[],"subsections":[{"level":5,"heading":"i. A covenant built on law and obedience becomes a covenant of works","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. A covenant built on promise and reception becomes a covenant of grace","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Qualification","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Not every covenant is a pure either/or case","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Some biblical covenants (like the ones with Israel) combine promise and obedience for different purposes within the same covenant","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. Federal headship","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion \u2014 the basic principle","bibleReferences":[],"subsections":[{"level":5,"heading":"i. God consistently deals with groups of people through one representative head \u2014 Adam, Noah, Abraham, David, Christ","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Proof \u2014 why headship is \u201cimmediate\u201d","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Descendants are connected to the head directly, regardless of how many generations separate them","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Supporting examples","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The wilderness generation's children still inherited Canaan through Abraham, not through their disobedient parents","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Levi is said to have tithed to Melchizedek \u201cin Abraham's loins\u201d (Hebrews 7:9\u201310)","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"c. Conclusion \u2014 what this means for covenant membership","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Belonging to a covenant is determined by relationship to its federal head, not simply by family lineage as such","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Parents can be the means by which a child enters a covenant, but the head \u2014 not the parents \u2014 is what actually grounds that membership","bibleReferences":[],"subsections":[]}]}]}]},{"level":2,"heading":"2. What is a Covenant's Function?","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Assertion \u2014 the basic function","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Covenants are the legal means by which God delegates and structures rule over a kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. They define a kingdom's boundaries, leaders, laws, and promises","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Application \u2014 the three kingdoms this book traces","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The kingdom of creation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. The kingdom of Israel","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. The kingdom of Christ","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Conclusion \u2014 how they relate to each other","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Each kingdom is governed by its own set of covenants","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. All three converge in the one final kingdom of God under Christ","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. A covenant is a divinely guaranteed commitment that defines a relationship with God","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. It functions as the legal foundation on which God establishes and governs a kingdom \u2014 the framework the rest of the book will trace from creation onward","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":4,"title":"Chapter 4: The Covenant of Works","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Objection: opponents point out that Genesis 1\u20133 never uses the word \u201ccovenant\u201d for God\u2019s dealings with Adam","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Response: examining what God actually did with Adam beyond his mere status as a creature reveals a genuine covenantal transaction, whether or not the word itself appears","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. Man\u2019s Created Condition","bibleReferences":["Genesis 1:31"],"subsections":[{"level":3,"heading":"a. Assertion: creation, and man within it, was good","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Proof: Genesis 1 declares this good seven times, summed up in \u201cexceedingly good\u201d (Genesis 1:31)","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Man\u2019s natural goodness sets the stage for what God offers beyond that natural condition","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Positive: by nature, Adam owed complete obedience to God as Creator","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Negative: by nature, God was not obligated to reward that obedience with anything beyond the approval of justice","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Comparison: Genesis 1 and Genesis 2 give complementary perspectives","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Genesis 1 = the macro/universal view \u2014 dominion over all the earth, filling and subduing it","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Genesis 2 = the local/micro view \u2014 the specific conditions under which that universal task begins","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Conclusion: Genesis 1 sets the scope of the coming covenant; Genesis 2 fills in the details","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"2. Man\u2019s Covenantal Condition","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Definition: a covenant = a commitment plus divine sanctions","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. God placed Adam under obligations beyond his created status, added sanctions to guarantee them, and committed to a reward \u2014 this sanctioned arrangement is the Covenant of Works","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. God placed Adam in the garden of Eden","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Genesis 2:8 \u2014 Eden was prepared and Adam was placed there","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Positive: Eden was a specially prepared location","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Negative: it was not Adam\u2019s original or natural starting place","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Assertion: Eden functioned as a temple, a sanctuary of God\u2019s special presence","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Its features echo temple imagery: eastern orientation, elevated/mountaintop location, precious stones, and trees","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Comparison: later biblical temples are described using language that draws on Eden\u2019s imagery, suggesting Eden is the prototype","bibleReferences":[],"subsections":[{"level":7,"heading":"God\u2019s presence is repeatedly manifested on mountaintops (Sinai, the Jerusalem temple, Mount Zion in Hebrews 12:22)","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The precious stones anticipate the tabernacle/temple\u2019s construction and Aaron\u2019s breastplate, and align with Revelation\u2019s gemstone imagery","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The trees anticipate the almond-tree-shaped Menorah (Exodus 25:31\u201339) and the tree of life named again in Revelation 22","bibleReferences":[],"subsections":[]}]},{"level":6,"heading":"3. Throughout redemptive history, God consistently refuses to allow sin into His holy spaces","bibleReferences":[],"subsections":[{"level":7,"heading":"Adam is banished from Eden after the fall","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The tabernacle, temple, and the land of Israel itself were kept pure, with expulsion threatened for violation","bibleReferences":[],"subsections":[]},{"level":7,"heading":"The individual believer is called a temple of the Holy Spirit, and the church must guard its membership boundaries","bibleReferences":[],"subsections":[]}]}]}]},{"level":4,"heading":"c. Conclusion: God made Eden a sanctuary and placed Adam there as its worker","bibleReferences":[],"subsections":[{"level":5,"heading":"i. By placing Adam there as worker, God granted him a specific realm to rule \u2014 Eden was Adam\u2019s kingdom, and he was its king","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"b. God appointed Adam federal head over his natural offspring","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: Adam was federal head over mankind by God\u2019s own appointment","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Romans 5:19 \u2014 Adam\u2019s one trespass brought condemnation on those he represented","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. 1 Corinthians 15:22 \u2014 \u201cin Adam all die\u201d","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. 1 Corinthians 15:47\u201349 \u2014 humanity bears the image of \u201cthe man of dust\u201d","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. Principle: as goes the king, so goes the kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Objection/complication: Genesis 1:28\u2019s commission to fill the earth is given in the plural, to both Adam and Eve together","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Response","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The universal scope of Genesis 1 must be read together with its local recapitulation in Genesis 2, where Adam alone is created, placed in the garden, and given his commission before Eve exists","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Eve\u2019s creation serves to help Adam carry out his commission \u2014 the command runs through Adam first, with Eve as his helper","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Conclusion: Adam is constituted federal head over his natural offspring; all mankind (Christ excepted, by virgin birth) is represented in him","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. God obligated Adam to a law of obedience","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First point: the basis of the law","bibleReferences":[],"subsections":[{"level":5,"heading":"i. By nature, Adam owed absolute obedience to God (the natural/moral law)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Beyond that, God added a positive law \u2014 commands arising purely from His revealed will","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Definition: the combination of natural law and this added positive command constitutes the Covenant of Works, named for the fact that obedience is its governing principle","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second assertion: Adam\u2019s task of \u201cworking\u201d and \u201ckeeping\u201d the garden (Genesis 2:15) was a priestly duty","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. The same Hebrew verbs are used in Numbers 3:6\u201310 to describe the Levites guarding the tabernacle","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. That passage warns that \u201cif any outsider comes near, he shall be put to death\u201d \u2014 the same principle applies to Adam\u2019s guarding of Eden","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Application: the general command to guard the sanctuary is made specific in Genesis 2:16\u201317 \u2014 free to eat any tree except the tree of the knowledge of good and evil, on pain of death","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Extension: Adam\u2019s role also carries a prophetic dimension","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Receiving God\u2019s word directly is itself a mark of prophetic commission (compare Moses relaying Levitical commands in Numbers 3:5\u20136)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. A prophet must not only receive God\u2019s word but also relay it purely and resist any challenge to it \u2014 Adam was responsible to guard against any threat to God\u2019s word in Eden","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Sequence and significance","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The priestly/prophetic commission is given to Adam first, then Eve is created as helper, then the universal commands of multiplication and dominion are given to both","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Two related aspects highlighted by this sequence","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Adam\u2019s role is kingly \u2014 bringing creation to consummation by filling the earth with a holy, God-honoring seed","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Adam\u2019s universal rule is determined by his local rule \u2014 whether Eden\u2019s boundaries expand to the whole earth depends entirely on his obedience regarding the one forbidden tree","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"e. Conclusion \u2014 summary","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The Covenant of Works combines the moral law with an added positive command","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Adam, as priest, prophet, and king of Eden, was to begin universal dominion by first succeeding in one specific, local test","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"d. God promised eternal life to Adam","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion: the tree of life symbolized the promised reward of eternal life","bibleReferences":[],"subsections":[{"level":5,"heading":"i. A bare law is not a covenant \u2014 Adam\u2019s obedience functioned within a covenant that suspended a promised reward on that obedience","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The tree of life represented the goal set before him","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: if Adam obeyed, the tree of life stood as a pledge of confirmed eternal life","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: confirmed eternal life and unbreakable communion with God were not part of Adam\u2019s natural constitution \u2014 he was sinless and upright, but still able to sin","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"iii. 1 John 3:4 defines sin as lawlessness; Adam was capable of violating God\u2019s law, and did","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iv. Proof from later Scripture","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Revelation 2:7 \u2014 the tree of life\u2019s benefits are promised to the one who perseveres in trusting Christ","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Revelation 22 \u2014 the tree of life appears again at the consummation, equated with eternal life","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Genesis 3:22\u201324 \u2014 Adam\u2019s expulsion is specifically tied to being barred from the tree of life","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"b. Second assertion: Paul\u2019s Adam-Christ comparisons confirm what Adam\u2019s obedience would have earned","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Argument from Romans 5: had Adam obeyed, the result would have paralleled Christ\u2019s obedience \u2014 righteousness for all he represented; Adam was the pattern for Christ\u2019s mission, not the reverse","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Argument from Romans 3:23: the \u201cglory\u201d Adam fell short of because of sin was a glory he could have attained through obedience in this covenant, a glory Christ has now entered and brings \u201cmany sons\u201d into (Hebrews 2:10)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Third assertion: no mercy was built into this covenant \u2014 Adam had to obey perfectly, personally, and perpetually","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. What it cost Christ to earn eternal life for His people","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. The severity with which the covenant\u2019s curse fell after the very first breach","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. The pattern of God\u2019s own Sabbath rest adds a future orientation \u2014 Adam was to bring about a kingdom and then enter rest, just as God did at creation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. The reward\u2019s dependence on the covenant is what makes it meritorious at all \u2014 apart from God\u2019s arrangement, Adam\u2019s obedience would have earned nothing","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Confirmed eternal life in righteousness was genuinely offered to Adam, and because such a reward could only come through God\u2019s free condescension, this constitutes a real covenant","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. If Adam had obeyed: the reward would belong to him and all he represented; Eden would extend to the whole earth; creation would reach consummation with no distinction between heaven and earth","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"e. God threatened Adam with sanctions","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Sanctions are what formalize covenantal commitments","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Assertion: God clearly threatened Adam with death for disobedience (Genesis 2:17)","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Negative: there was no allowance for mercy, no room for partial fulfillment, no admission of failure","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Consequence: if Adam broke God\u2019s rule, he would surely die, his commission would end in ruin, and the seed he was meant to bring to glory would fall with him","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Symbol: the tree of the knowledge of good and evil functioned as the sacramental symbol of this threat, paired against the tree of life as the symbol of the promise","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Conclusion: its ongoing presence served as a constant reminder of the necessity of obedience and the cost of unfaithfulness","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"f. God made a Covenant of Works with Adam","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: taken together, God\u2019s dealings with Adam beyond his natural condition constitute a genuine Covenant of Works","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Summary of the evidence: a defined kingdom, a federal head, a law of obedience, a promised reward, and a threatened curse \u2014 all present, even without the explicit word \u201ccovenant\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof: Nehemiah Coxe argued that God dealt with Adam \u201cnot only upon Terms of a Law, but in a way of Covenant,\u201d and that where the thing itself is sufficiently revealed, there is no need to insist on exact terminology","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Objection considered seriously \u2014 why this matters","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Denying this foundational doctrine undermines the heart of salvation itself","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof/consequence (Coxe): only on the basis of such a covenant could Adam\u2019s posterity be involved in his standing or falling \u2014 deny the covenant, and that involvement becomes unaccountable","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. If Adam\u2019s federal headship is denied: there is no way for mankind to have fallen in him, no clear reason for the incarnation, no clear basis for God\u2019s wrath or humanity\u2019s spiritual deadness, and no framework for the imputation central to Romans 5","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Caution against a purely negative reading","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The covenant threatens death, but it is only ominous because Adam failed \u2014 God\u2019s covenants are always designed for man\u2019s good","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof (Coxe): as to its terms, this was a covenant of works; as to its relational privilege, a covenant of friendship; as to its reward, a covenant of rich bounty and goodness \u2014 though it included no pardoning mercy","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Conclusion: the Covenant of Works was a supreme privilege and blessing; underestimating that truth leads to underestimating the depth of Adam\u2019s failure","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"g. God tested Adam\u2019s obedience","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First point: the nature of the test","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The Covenant of Works was not an open-ended demand \u2014 it had a definite goal, requiring a definable probationary test","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The \u201ctripwire\u201d of that test was the positive command regarding the tree of the knowledge of good and evil","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Adam\u2019s universal commission depended entirely on this one local command","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second point: the failure itself","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Comparison: just as Jesus was later tempted in the wilderness, Adam was tempted in the garden","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Adam was called to keep the sanctuary pure and uphold God\u2019s word","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Eve was deceived by the serpent","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Adam listened to his wife rather than exercising his commissioned dominion","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. As a result, he failed to obey, the covenant\u2019s sanctions were fully activated, and his sin was imputed to all his posterity","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"c. Proof of what was at stake: Romans 3:23 and 5:17\u201318 indicate that had Adam obeyed, he would have attained God\u2019s glory and constituted \u201cthe many\u201d as righteous","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Illustration (Meredith Kline): Adam\u2019s probation is described as a kind of judicial combat, requiring one decisive act of righteousness akin to a victory in battle against Satan \u2014 a victory that, had it been won, would have been imputed to all whom Adam represented","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Conclusion: Adam failed this test, and mankind died in him \u2014 setting up the transition to humanity\u2019s cursed condition","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. Man\u2019s Cursed Condition","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Problem: God said Adam would \u201csurely die\u201d the day he ate the fruit, yet Adam did not die physically that day \u2014 does this mean the curse wasn\u2019t actually activated?","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Resolution: no \u2014 the curse was poured out in full; death, in multiple senses, descended on Adam that very day","bibleReferences":[],"subsections":[]},{"level":3,"heading":"a. Death","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion: because Adam was federal head, his curse fell on all of mankind collectively","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Romans 5:12 \u2014 sin and death spread to all because all sinned in Adam","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. 1 Corinthians 15:21\u201322 \u2014 \u201cin Adam all die\u201d","bibleReferences":[],"subsections":[]}]},{"level":5,"heading":"ii. Consequence: this is collective, imputed death \u2014 mankind\u2019s legal record is Adam\u2019s record","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Second point: physical death","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Not instant, but certain \u2014 disease, weakness, and eventual death await all","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. 1 Corinthians 15 \u2014 bearing \u201cthe image of the man of dust,\u201d humanity returns to dust","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Third point: spiritual death \u2014 man\u2019s immaterial part is already dead, even before the body dies","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Proof: Ephesians 2:1\u20133 \u2014 \u201cdead in trespasses and sins,\u201d \u201cchildren of wrath\u201d by nature","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive: man\u2019s mind still knows God exists (Romans 1)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Negative: man suppresses that knowledge in unrighteousness and exchanges the truth for a lie","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iv. Further proof: Ephesians 4:18 (mind darkened), 1 Corinthians 2:14 (the natural man cannot discern spiritual things)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"v. Fallen man\u2019s rejection of truth is both passive (it \u201cjust happens\u201d) and active (he suppresses, distorts, and disbelieves)","bibleReferences":[],"subsections":[]},{"level":5,"heading":"vi. Consequence: man cannot choose or do spiritual good","bibleReferences":[],"subsections":[{"level":6,"heading":"1. Positive: man retains the power of choice and remains a free agent","bibleReferences":[],"subsections":[]},{"level":6,"heading":"2. Negative: that will is not free from a nature bent toward sin, and cannot choose or accomplish spiritual good","bibleReferences":[],"subsections":[]},{"level":6,"heading":"3. Qualification: man is capable of civic or outwardly good acts, but nothing that pleases God or satisfies His law (Matthew 7:17\u201318; Romans 5:6; 8:7\u20138; Titus 3:3)","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"d. Fourth point: eternal death \u2014 the most severe dimension","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Matthew 25 and Revelation 20 describe a final division between everlasting life and everlasting punishment","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. This is the direct opposite of the eternal life Adam would have secured through obedience, reinforced by his being barred specifically from the tree of life (Genesis 3:22)","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Conclusion: the cursed condition involves death in every sense, culminating in permanent exclusion from God\u2019s glory","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. The abrogation of the covenant of works","bibleReferences":[],"subsections":[{"level":4,"heading":"a. First assertion","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Positive: the covenant remains \u201cin force\u201d today in the sense that its curse still applies to all Adam\u2019s offspring","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Negative: it does not remain in force in the sense of still offering life for obedience to its commands","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"b. Proof \u2014 why this is so","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The Covenant of Works depended on positive laws tied to Eden specifically; with no more Eden or sacramental trees, there are no more such commands to obey","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. The covenant was made with Adam as federal head, not with each individual descendant directly","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"c. Conclusion of this point: the promise of the Covenant of Works is permanently closed off","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Illustration: returning to the path of the Covenant of Works after the fall leads not to heaven but back to a cursed, guarded Eden \u2014 the way is blocked not only by human inability but by God\u2019s active barring of it","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"d. Second point \u2014 the moral law\u2019s continued authority","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Qualification: the abrogation of the covenant\u2019s positive laws does not touch the ongoing authority of the moral law","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Proof (Coxe): \u201cThe Law of Creation binds when the Covenant of Creation is broken\u201d \u2014 retained as a \u201crule of life\u201d","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. This obligation carries no promise attached, since the duty to obey belongs to the Creator-creature relationship by nature, while reward does not","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"e. Third point \u2014 effect on the mandate to work and multiply","bibleReferences":[],"subsections":[{"level":5,"heading":"i. The obligation to work and multiply remains, but the curse changes its character","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. First, human work can never secure more than a somewhat longer or easier life","bibleReferences":[],"subsections":[]},{"level":5,"heading":"iii. Second, the specific curses on man and woman directly hinder those mandates \u2014 painful childbearing for the woman, resistant ground for the man","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"f. Conclusion: the Covenant of Works is abrogated as to its promises and positive laws, but its moral demands and curses continue to bind and condemn","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. A merciful curse","bibleReferences":[],"subsections":[{"level":4,"heading":"a. Assertion: God did not immediately impose the full severity of the curse \u2014 an act of mercy","bibleReferences":[],"subsections":[]},{"level":4,"heading":"b. Proof: before pronouncing curses on Adam and Eve, God first curses the serpent (Genesis 3:15), and that curse on Satan contains a promise of salvation for mankind","bibleReferences":[],"subsections":[]},{"level":4,"heading":"c. Adam and Eve were hopeless in themselves at that moment, yet God speaks of deliverance before announcing their own curses","bibleReferences":[],"subsections":[]},{"level":4,"heading":"d. Genesis 3:15 promises enmity between the serpent and the woman\u2019s offspring, and that offspring\u2019s eventual victory","bibleReferences":[],"subsections":[]},{"level":4,"heading":"e. Contrast: by following Satan, Adam and Eve had aligned themselves with him as king; yet Satan\u2019s own curse places him lowest of all, pictured by the snake\u2019s position in the dust","bibleReferences":[],"subsections":[]},{"level":4,"heading":"f. Significance of the sequence: because Eve\u2019s offspring is promised before Adam and Eve\u2019s own curses are pronounced, their punishment becomes chastisement rather than pure condemnation \u2014 discipline from a father, not a verdict from a judge","bibleReferences":[],"subsections":[]},{"level":4,"heading":"g. They are not immediately freed from the Covenant of Works\u2019 lesser curses, but they are freed from its ultimate curse of eternal death; their hope now rests in a coming descendant","bibleReferences":[],"subsections":[]},{"level":4,"heading":"h. Clarification on what this promise is not","bibleReferences":[],"subsections":[{"level":5,"heading":"i. Negative: it is not a new command for self-improvement or self-deliverance, and not a law paired with a threat","bibleReferences":[],"subsections":[]},{"level":5,"heading":"ii. Positive: it is a promise God Himself must fulfill, to be simply received and believed","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"i. Conclusion: this moment marks the earliest dawning of the mystery of Christ, His covenant, and His kingdom","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. The Protological Nature of the Kingdom","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Definition: \u201cprotology\u201d refers to the foundational symbols and patterns that God establishes early on and repeats throughout the rest of Scripture","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Eden and the Covenant of Works function as this foundational pattern \u2014 the movement from protology to eschatology is another way of describing the movement from type to antitype","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Comparison","bibleReferences":[],"subsections":[{"level":4,"heading":"i. In Eden, a son of God is commissioned to bring the whole cosmos to a consummated, sinless kingdom","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Israel is later portrayed as a new son of God in a new paradise, under a new covenant, with its own temple, righteousness requirements, and promises of life","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Christ, the true and eternal Son of God, receives an everlasting covenant granting life in an eternal kingdom, again marked by temple, righteousness, and promised life","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Through the Covenant of Works, God delegated dominion over Eden to Adam, making him king of that realm","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. God established his federal headship, gave him a law of obedience, promised him a reward, and threatened him with a curse \u2014 all through this one covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. The covenant\u2019s purpose was to bring creation to consummation, extending Eden until the whole cosmos became God\u2019s dwelling","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Because Adam broke this covenant, creation as a whole remains under its government and its curse","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Yet God promised deliverance from that curse \u2014 and the rest of the book traces the unfolding of that promise","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":5,"title":"Chapter 5: The Noahic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[{"level":3,"heading":"a. The Covenant of Works has all of creation in view, and so does the Noahic Covenant \u2014 another covenant governing the kingdom of creation and its members, mankind","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Context: as man multiplied, so did his sinfulness, to the point that it seemed believers might be nearly wiped out","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. It is in that context that God sends the flood as judgment on mankind","bibleReferences":[],"subsections":[]}]},{"level":2,"heading":"1. A New Creation and Commission","bibleReferences":["Genesis 8:21","Genesis 9:1\u20132"],"subsections":[{"level":3,"heading":"a. First assertion: the flood narrative is deliberately composed to echo the Genesis 1 creation account","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Proof","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The Ruach/wind and the great deep reappear","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Dry land emerges from the waters again","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. Birds again fill the heavens, and man and animals fill the earth","bibleReferences":[],"subsections":[]},{"level":5,"heading":"4. Noah, like Adam, receives a commission to be fruitful and fill the earth","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Qualification \u2014 what this parallel does NOT mean","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: it does not mean man returns to paradise or receives a new one","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Negative: it does not mean man returns to innocence or obtains a new righteousness","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Proof: Genesis 8:21 \u2014 \u201cthe intention of man\u2019s heart is evil from his youth\u201d","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Consequence","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The flood saved the lives of Noah and his family","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. But it did not save their souls, and did not change the heart of man","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. Positive: the face of the earth may be less full of wickedness","bibleReferences":[],"subsections":[]},{"level":5,"heading":"4. Negative: the heart of man remains just as corrupt as before","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"v. Conclusion: the world Noah enters is not Eden, not paradise, and not a sacred place of God\u2019s presence \u2014 it is simply the fallen world","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Second assertion: the commission given to Noah also echoes Eden, but differs sharply from Adam\u2019s","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Comparison","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Genesis 1\u2019s commission to Adam and Eve carried a positive tone \u2014 building, mastery, usefulness, cooperation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Genesis 9\u2019s commission to Noah achieves mastery over creation through fear and dread rather than wisdom and excellence","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Parallel: the same kind of \u201cfear and dread\u201d language later describes how the Canaanite nations will regard Israel","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Application: Noah and mankind are called to build, cultivate, and establish human civilization, making use of the natural world","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Principle: this is a cultural mandate that functions as part of a covenant ruling a kingdom, and it applies equally to all mankind","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Consequence: everyone today is accountable to this covenant, since federal headship reaches every generation while the covenant remains active","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vi. Application: all mankind \u2014 men and women \u2014 are called to build structured, successful societies","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: not called to idleness or despair","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Positive: called to work, despite the resistance and difficulty the curse introduced","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"vii. Contrast with Adam\u2019s original task","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Adam and Eve were called to extend Eden and make the whole world a temple, gradually producing a holy, consummated paradise","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Noah\u2019s task differs sharply","bibleReferences":[],"subsections":[{"level":6,"heading":"(a) Present-day cultural achievement, however enjoyable by common grace, does not build the consummated kingdom of God","bibleReferences":[],"subsections":[]},{"level":6,"heading":"(b) It does not make the world a temple","bibleReferences":[],"subsections":[]},{"level":6,"heading":"(c) It does not fill the earth with a holy seed","bibleReferences":[],"subsections":[]}]}]},{"level":4,"heading":"viii. Conclusion: even faithful obedience to this commission does not advance a holy land, culture, or family in the way Adam\u2019s commission would have","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Third assertion: the Noahic Covenant is therefore not a covenant of salvation or eternal life","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Proof/consequence: success or failure in keeping its commission brings neither eternal life nor eternal death","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Reason: mankind is already condemned in Adam, and at this point the only known escape was God\u2019s promise that Eve\u2019s offspring would crush the serpent\u2019s head","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Qualification: though it offers no eternal life itself, the Noahic Covenant still serves that greater promise of salvation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. How: its renewed commission to reproduce and expand provides the means by which the promised seed of Eve can eventually be born","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Historical logic: mankind\u2019s evil had grown so extreme that it threatened to wipe out the godly line entirely, so the Lord judged humanity through the flood in order to preserve His promise, and human multiplication can now resume serving that purpose","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vi. Conclusion: this is Noah\u2019s \u2014 and mankind\u2019s \u2014 new commission","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"2. A Judicial Retribution","bibleReferences":["Genesis 9:5\u20137"],"subsections":[{"level":3,"heading":"a. First assertion: God establishes and governs His kingdoms through covenant; in the Noahic Covenant, He both renews the cultural mandate and establishes universal laws of justice, binding on every society","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Text: Genesis 9:5\u20137 \u2014 God will require a reckoning for human bloodshed; whoever sheds man\u2019s blood, by man his blood shall be shed, because man bears God\u2019s image","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Application: this command binds all mankind, everywhere","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Principle: man\u2019s ongoing commission is still to be fruitful and multiply (repeated in v. 7)","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Problem: murder directly works against that commission","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Resolution: to restrain mankind\u2019s sinfulness and prevent extreme bloodshed, murderers are made subject to death","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vi. Consequence: this establishes a genuine system of legal and judicial retribution within society","bibleReferences":[],"subsections":[]},{"level":4,"heading":"vii. Explanation: this authority to punish wrongdoing is real power, derived from God Himself through this covenant","bibleReferences":[],"subsections":[]},{"level":4,"heading":"viii. Dual character of the death penalty","bibleReferences":[],"subsections":[{"level":5,"heading":"1. It functions as an act of God\u2019s judgment on the murderer","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. It functions as an act of deliverance for the society itself","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"b. Second assertion: the Noahic Covenant gives human societies two basic, related responsibilities","bibleReferences":[],"subsections":[{"level":4,"heading":"i. To preserve life","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. To preserve the family","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Reasoning: since mankind is to be fruitful and multiply, and multiplication happens through families, society\u2019s core task is to promote and protect both","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Consequence: any society or government that corrupts the family, or murders the innocent, stands in direct treason against God","bibleReferences":[],"subsections":[{"level":5,"heading":"1. It misuses the very authority \u2014 \u201cthe sword\u201d \u2014 entrusted to it, turning it on the innocent instead of the guilty","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"v. Application to a contemporary example","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Assertion: government-sponsored, legally protected abortion is a stark instance of this violation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Reasoning: nothing opposes mankind\u2019s basic commission to be fruitful and multiply more directly than killing one\u2019s own children and shielding that killing by law","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. Parallel example: the promotion of abortion alongside the erosion of marriage (widespread divorce, same-sex unions, sexual immorality) together constitute a rejection of the most basic duties the Noahic Covenant establishes","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. Conclusion: the Noahic Covenant functions as a more fundamental constitution than any nation\u2019s own founding documents","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Application: society is obligated to","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Promote, preserve, and protect the life of individuals","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Promote, preserve, and protect the life of the family","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Consequence: this requires punishing the wicked, executing murderers, and cultivating genuinely loving, thriving families","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"3. A Promised Preservation","bibleReferences":["Genesis 9:8\u201317","Genesis 8:22"],"subsections":[{"level":3,"heading":"a. First assertion: covenants can be summarized as \u201cI will\u201d/\u201cyou will\u201d statements; having laid out man\u2019s obligations, God now makes His own commitment (Genesis 9:8\u201317)","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Text summary: God establishes His covenant with Noah, his offspring, and every living creature, promising the flood waters will never again destroy all flesh, with the rainbow given as the covenant\u2019s sign","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Scope of the promise, steadily expanding","bibleReferences":[],"subsections":[{"level":5,"heading":"1. From Noah","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. To his family","bibleReferences":[],"subsections":[]},{"level":5,"heading":"3. To all mankind","bibleReferences":[],"subsections":[]},{"level":5,"heading":"4. To all the earth","bibleReferences":[],"subsections":[]},{"level":5,"heading":"5. To all flesh","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Promise: the earth will never again be destroyed by a global flood","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Sacrament: the rainbow is given as a visible sign and promise of this reality","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"b. Second assertion: God further promises a stable natural order (Genesis 8:22 \u2014 seasons, cold and heat, day and night will continue predictably)","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Qualification: this promise holds regardless of human obedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Contrast: though this covenant does carry obligations, its promised blessings themselves are not withdrawn for disobedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Conclusion: God will not flood the earth again, and the rainbow stands as His visible pledge of that to the world","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"c. Third point \u2014 clarifying the scope of this preservation","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Application: the sun shines on the righteous and the wicked alike","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Clarification on the scope of preservation","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Negative: the promise is not one of eternal, unending preservation","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Positive: it is specifically that a flood will never again destroy the earth","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"iii. Clarification: this promise is not conditioned on human obedience","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Qualification: God may still judge particular peoples or nations for their wickedness, but the whole of mankind will not suffer a repeat of universal judgment by flood","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Purpose and conclusion of this section","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Purpose: this promise creates a stable platform on which God\u2019s larger plan of salvation can play out","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Explanation: the mystery of Christ unfolds within this theater of preservation","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Consequence: God\u2019s people, whether before or after Christ\u2019s coming, can know that the earth will endure until every one of God\u2019s promises has been fulfilled","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Conclusion: this covenant offers real comfort \u2014 however unstable the world seems, God\u2019s promises will still be kept","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"4. A Common Cursed Kingdom of Common Grace","bibleReferences":[],"subsections":[{"level":3,"heading":"a. First assertion (thesis): combining these elements shows that the kingdom of creation is best described as a common, cursed kingdom sustained by common grace","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. Proof: the scope of Adam\u2019s and Noah\u2019s covenants is identical \u2014 both have the whole world in view","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Adam began in Eden, but his commission was to extend Eden to the whole world, and he served as federal head of all mankind","bibleReferences":[],"subsections":[{"level":5,"heading":"1. Proof: in Adam\u2019s fall, all sinned; all creation is governed by the Covenant of Works","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. Proof: when Adam broke that covenant, all creation was cursed, both mankind and the ground itself","bibleReferences":[],"subsections":[]}]},{"level":4,"heading":"ii. Conclusion: God established the kingdom of creation through the Covenant of Works, and creation remains under its judgment and curse","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Noah\u2019s case: the flood narrative and his commission are framed as a new creation and new commission, echoing Adam\u2019s situation rather than repeating it exactly","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Parallel: just as Adam\u2019s covenant encompassed all mankind and creation, so does Noah\u2019s","bibleReferences":[],"subsections":[]},{"level":4,"heading":"v. Conclusion: the kingdom of creation is governed by two covenants together","bibleReferences":[],"subsections":[{"level":5,"heading":"1. The Covenant of Works curses mankind","bibleReferences":[],"subsections":[]},{"level":5,"heading":"2. The Noahic Covenant stabilizes that cursed world so redemptive history can unfold and God\u2019s promises can be fulfilled","bibleReferences":[],"subsections":[]}]}]},{"level":3,"heading":"c. Clarification: the Noahic Covenant and the Covenant of Works are not in tension \u2014 they simply serve different purposes","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Contrast: the Covenant of Works curses and condemns; the Noahic Covenant governs how to live within that cursed world","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Both remain active covenants through which God governs mankind and grants human authority","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Note: Adam forfeited his own authority, but in Noah, all people are still called to build culture and be fruitful and multiply","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"d. Second assertion: this kingdom of creation is the common kingdom in which all mankind and all human societies live today","bibleReferences":[],"subsections":[{"level":4,"heading":"i. Its curses apply to everyone; its promises and blessings apply to everyone","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Clarification: this kingdom does not itself offer salvation or saving grace","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Positive: it is nonetheless a genuine kindness from God that He gives rain and sunshine to all mankind in common, rather than curse and death","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iv. Conclusion: this is properly called the realm of common grace \u2014 God preserves the whole world, and the unbeliever has just as much claim to this common kindness as the believer, since both are citizens of the same common, cursed kingdom of common grace","bibleReferences":[],"subsections":[]}]},{"level":3,"heading":"e. Illustration: Ecclesiastes describes this as life \u201cunder the sun\u201d","bibleReferences":[],"subsections":[{"level":4,"heading":"i. The system often doesn\u2019t work as it should \u2014 hard work doesn\u2019t always pay off, and laziness sometimes does","bibleReferences":[],"subsections":[]},{"level":4,"heading":"ii. Yet everyone is cursed, and everyone eventually dies","bibleReferences":[],"subsections":[]},{"level":4,"heading":"iii. Conclusion (drawn from Ecclesiastes): humanity\u2019s basic obligation in this common kingdom is simply to fear God and keep His commandments \u2014 to trust and obey, and nothing more","bibleReferences":[],"subsections":[]}]}]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[{"level":3,"heading":"a. Covenant and kingdom together give a clear, biblical way of understanding the world we live in","bibleReferences":[],"subsections":[]},{"level":3,"heading":"b. We inhabit the kingdom of creation \u2014 a common, cursed kingdom of common grace \u2014 established and governed jointly by the Covenant of Works and the Noahic Covenant","bibleReferences":[],"subsections":[]},{"level":3,"heading":"c. Comparison: this kingdom is marked for eventual destruction under the Covenant of Works (compared to Bunyan\u2019s \u201cCity of Destruction\u201d)","bibleReferences":[],"subsections":[]},{"level":3,"heading":"d. Yet it is also granted preservation under the Noahic Covenant, for the sake of fulfilling all of God\u2019s promises","bibleReferences":[],"subsections":[]},{"level":3,"heading":"e. Conclusion: all mankind, believer and unbeliever alike, benefits from that preserving kindness and common grace","bibleReferences":[],"subsections":[]}]}]},{"chapterNumber":6,"title":"Chapter 6: The Abrahamic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[]},{"level":2,"heading":"1. The Initiation of the Covenant","bibleReferences":["Genesis 12:1\u20137"],"subsections":[]},{"level":2,"heading":"a. The federal head","bibleReferences":["Genesis 12:2"],"subsections":[]},{"level":2,"heading":"b. The inheritance of Canaan","bibleReferences":[],"subsections":[]},{"level":2,"heading":"c. The blessing for the nations","bibleReferences":["Ephesians 1:10"],"subsections":[]},{"level":2,"heading":"2. The Confirmation of the Covenant","bibleReferences":["Genesis 15:18"],"subsections":[]},{"level":2,"heading":"3. The Expansion of the Covenant","bibleReferences":["Genesis 15:18","Genesis 12:7","Genesis 17:4\u20138","Genesis 17:6","Genesis 35:11","Genesis 49:8\u201310","Genesis 17:9","Genesis 17:14"],"subsections":[]},{"level":2,"heading":"4. The Realization of the Covenant","bibleReferences":["Joshua 21:43\u201345","Nehemiah 9:7\u20138","1 Kings 4:20","Hebrews 11:12","Luke 1:54\u201355","Luke 1:68"],"subsections":[]},{"level":2,"heading":"5. The Foundation of the Old Covenant","bibleReferences":["Genesis 28:4","Genesis 35:12","Exodus 6:2\u20134","Exodus 32:13","Deuteronomy 1:8","Joshua 1:6","Psalm 105:6\u201311","Jeremiah 11:2\u20135","Romans 11:1","Acts 3:25\u201326","Acts 7:2\u20133","Luke 3:8\u20139"],"subsections":[]},{"level":2,"heading":"a. The Abrahamic Covenant anticipates the Mosaic Covenant","bibleReferences":["Genesis 15:13"],"subsections":[]},{"level":2,"heading":"b. The Abrahamic covenant anticipates the Davidic Covenant","bibleReferences":[],"subsections":[]},{"level":2,"heading":"c. The Abrahamic Covenant anticipates the New Covenant","bibleReferences":["Romans 4:10","Hebrews 11:9\u201310"],"subsections":[]},{"level":2,"heading":"d. The Abrahamic covenant echoes Eden","bibleReferences":[],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[]}]},{"chapterNumber":7,"title":"Chapter 7: The Mosaic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. The promise of oppression and affliction","bibleReferences":["Genesis 15:13\u201316","Exodus 2:23\u201325","Exodus 12:40\u201341"],"subsections":[]},{"level":2,"heading":"b. The promise of liberation and fulfilment","bibleReferences":["Exodus 3:13\u201317","Exodus 6:1\u20135","Psalm 77:20"],"subsections":[]},{"level":2,"heading":"2. The Kind of Covenant","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. Its laws","bibleReferences":["Exodus 19:3\u20138","Exodus 24:3\u20138","Hebrews 9:18\u201323","Exodus 34:27\u201328"],"subsections":[]},{"level":2,"heading":"b. Its promises","bibleReferences":["Jeremiah 11:2\u20135","Jeremiah 7:3\u20137","Exodus 32:13"],"subsections":[]},{"level":2,"heading":"c. Its threats","bibleReferences":["Deuteronomy 6:20","Deuteronomy 11:26\u201328","Deuteronomy 27:26","Deuteronomy 29:22\u201328","Deuteronomy 30:15\u201320"],"subsections":[]},{"level":2,"heading":"3. The Kindness of the Covenant","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. The absolute dominion of God","bibleReferences":[],"subsections":[]},{"level":2,"heading":"b. The promises to Abraham","bibleReferences":["Exodus 32:13\u201314"],"subsections":[]},{"level":2,"heading":"c. The sacrificial system","bibleReferences":["Leviticus 5:14\u201319","Leviticus 16:21\u201322"],"subsections":[]},{"level":2,"heading":"d. The history of Israel","bibleReferences":["Deuteronomy 4:25\u201331","Nehemiah 9:7\u20138"],"subsections":[]},{"level":2,"heading":"4. The Function of the Covenant","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. The covenant governs the people","bibleReferences":["Deuteronomy 4:1\u20132"],"subsections":[]},{"level":2,"heading":"b. The covenant governs the priesthood","bibleReferences":["Exodus 40:12\u201316","Leviticus 10:1\u20132"],"subsections":[]},{"level":2,"heading":"c. The covenant governs the kingship","bibleReferences":["Deuteronomy 17:14\u201320"],"subsections":[]},{"level":2,"heading":"d. The covenant governs the prophets","bibleReferences":["Numbers 12:6","Deuteronomy 13:1\u20135"],"subsections":[]},{"level":2,"heading":"e. The covenant governs blessing and cursing","bibleReferences":["Deuteronomy 27:9\u201310","Deuteronomy 28:1\u20132","Deuteronomy 31:9\u201313","Deuteronomy 32:45\u201347"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":["Hebrews 10:1"],"subsections":[]}]},{"chapterNumber":8,"title":"Chapter 8: The Davidic Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. The promises of the Abrahamic Covenant","bibleReferences":["Genesis 17:6"],"subsections":[]},{"level":2,"heading":"b. The problems of the Mosaic Covenant","bibleReferences":["Judges 2:10\u201311","Judges 21:25"],"subsections":[]},{"level":2,"heading":"c. The preference of the people","bibleReferences":["1 Samuel 8:7\u20139"],"subsections":[]},{"level":2,"heading":"d. The prospect of consummation","bibleReferences":["Deuteronomy 12:8\u201312"],"subsections":[]},{"level":2,"heading":"2. The Blessings of the Covenant","bibleReferences":["2 Samuel 7:8\u201316"],"subsections":[]},{"level":2,"heading":"a. An established throne","bibleReferences":[],"subsections":[]},{"level":2,"heading":"b. Rest and prosperity in Canaan","bibleReferences":["1 Kings 8:56","Psalm 144:1\u20132"],"subsections":[]},{"level":2,"heading":"c. The presence and protection of God","bibleReferences":["1 Kings 6:12\u201313"],"subsections":[]},{"level":2,"heading":"3. The Conditions of the Covenant","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. Guard God's sanctuary","bibleReferences":["2 Samuel 7:13"],"subsections":[]},{"level":2,"heading":"b. Keep God's law","bibleReferences":[],"subsections":[]},{"level":2,"heading":"c. Represent God's people","bibleReferences":[],"subsections":[]},{"level":2,"heading":"4. The Sanctions of the Covenant","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. The judgment of God himself","bibleReferences":["2 Samuel 7:14","Psalm 132:11\u201312","1 Kings 8:25\u201326"],"subsections":[]},{"level":2,"heading":"b. Expulsion from the land of Canaan","bibleReferences":["1 Kings 9:4\u20139","1 Kings 11:11\u201313","2 Kings 23:26\u201327"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[]}]},{"chapterNumber":9,"title":"Chapter 9: The Messiah of the Old Covenant","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[]},{"level":2,"heading":"1. The Messianic Purpose of the Old Covenant","bibleReferences":["Romans 9:4","Ephesians 2:12","Hebrews 10:1"],"subsections":[]},{"level":2,"heading":"2. The Messianic Hope of the Old Covenant","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. The present Messiah","bibleReferences":["Psalm 18:50","Psalm 20:6\u20139","Psalm 132:10\u201318"],"subsections":[]},{"level":2,"heading":"b. The future Messiah","bibleReferences":["Hosea 6:7","Psalm 89:28\u201349","Jeremiah 33:14\u201318","Isaiah 9:1\u20137"],"subsections":[]},{"level":2,"heading":"3. The Messianic Promise of a New Covenant","bibleReferences":["Ezekiel 37:24\u201328","Jeremiah 31:31\u201334"],"subsections":[]},{"level":2,"heading":"4. The Messianic Inclusion of the Nations","bibleReferences":["Micah 4:1\u20134","Isaiah 2:2\u20134","Haggai 2:6\u20139","Isaiah 11:1\u201310"],"subsections":[]},{"level":2,"heading":"5. The Typological Nature of the Kingdom","bibleReferences":["Luke 1:26\u201333","Mark 1:14\u201315","John 1:41"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[]}]},{"chapterNumber":10,"title":"Chapter 10: The Ministry of the Christ","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[]},{"level":2,"heading":"1. The Gospel of the Kingdom","bibleReferences":["Mark 1:14\u201315","Luke 4:18","Matthew 11:28\u201330","Matthew 9:11\u201312","Mark 1:34","John 10:14\u201318","Ezekiel 34:22\u201325","John 11:25\u201327"],"subsections":[]},{"level":2,"heading":"2. The Kingdom of Heaven","bibleReferences":["John 18:36","John 3:3\u20136","Matthew 8:11\u201312","John 8:39","Matthew 16:16\u201319","Matthew 18:1\u20134","Matthew 8:10\u201312"],"subsections":[]},{"level":2,"heading":"3. The King of the Kingdom","bibleReferences":["Matthew 5:17\u201320","Matthew 21:9"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[]}]},{"chapterNumber":11,"title":"Chapter 11: The Covenant of Redemption","sections":[{"level":2,"heading":"Introduction","bibleReferences":["2 Timothy 1:9","Titus 1:2"],"subsections":[]},{"level":2,"heading":"1. The Parties of the Covenant","bibleReferences":["Isaiah 42:1\u20137","Isaiah 49:8\u20139","Isaiah 50:4\u20139","Luke 4:17\u201321"],"subsections":[]},{"level":2,"heading":"a. The Son's commitments","bibleReferences":["John 10:17\u201318","Psalm 2:6\u20139","Psalm 110:4","Hebrews 7:28","Isaiah 61:1\u20132","John 17:8"],"subsections":[]},{"level":2,"heading":"b. The Father's commitments","bibleReferences":["Isaiah 42:6","Isaiah 49:8","Isaiah 50:7","Luke 1:35","Matthew 12:27\u201328","Hebrews 9:14","Isaiah 53:10\u201312","Philippians 2:8\u201311","1 John 3:8"],"subsections":[]},{"level":2,"heading":"3. The Fulfillment of the Covenant","bibleReferences":["Philippians 2:5\u20138","Isaiah 50:5\u20137","Isaiah 53:10\u201312","Acts 2:32\u201333","Hebrews 10:12\u201314","Revelation 5:12","Hebrews 5:3"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[]}]},{"chapterNumber":12,"title":"Chapter 12: The New Covenant of Grace","sections":[{"level":2,"heading":"Introduction","bibleReferences":["Matthew 1:1","Luke 1:68\u201375","Galatians 4:4\u20135"],"subsections":[]},{"level":2,"heading":"1. The Establishment of the New Covenant","bibleReferences":["Hebrews 8:6","Hebrews 9:11\u201315","Ephesians 2:16","Colossians 1:20\u201322","Hebrews 9:24\u201326"],"subsections":[]},{"level":2,"heading":"2. The Blessings of the New Covenant","bibleReferences":["Jeremiah 31:31\u201334","Hebrews 8:8\u201313"],"subsections":[]},{"level":2,"heading":"a. Justification","bibleReferences":["Romans 5:17\u201319","Hebrews 10:14","Psalm 103:12","Isaiah 53:5","Hebrews 9:9\u201310","Hebrews 9:13\u201314","Isaiah 53:11","Romans 5:18\u201319","Romans 5:1\u20132","Romans 10:9\u201313"],"subsections":[]},{"level":2,"heading":"b. Regeneration and Sanctification","bibleReferences":["Jeremiah 31:33\u201334","Ezekiel 36:26\u201327","Deuteronomy 10:16","Jeremiah 4:4","Deuteronomy 30:6","John 3:3","Colossians 1:12","1 Corinthians 15:48","Ephesians 4:23","Colossians 3:10","Romans 6:17\u201318","Ephesians 2:1\u201310","2 Corinthians 3:5\u20139","Romans 3:20","Romans 5:1\u20132","Isaiah 54:13","John 6:45","Jeremiah 31:34","1 John 2:20\u201321","Romans 10:17","James 1:18","1 Peter 1:23"],"subsections":[]},{"level":2,"heading":"c. Adoption and Preservation","bibleReferences":["John 1:12\u201313","Romans 8:15","1 John 3:1\u20132","Hebrews 12:3\u201311","Jeremiah 32:40"],"subsections":[]},{"level":2,"heading":"d. Resurrection and Glorification","bibleReferences":["Psalm 16:10","Romans 4:25","John 6:39\u201340","Hebrews 2:10","Colossians 1:18","1 Corinthians 15:45","Colossians 3:1\u20134","1 Corinthians 15:54\u201357","Mark 3:22\u201327","Colossians 1:12","Romans 8:18\u201325","1 Corinthians 2:9","2 Corinthians 4:13\u201318","Revelation 22:4","2 Corinthians 4:6","Psalm 73:23\u201328","Psalm 16:11"],"subsections":[]},{"level":2,"heading":"3. The Foundation of the New Covenant","bibleReferences":["Hebrews 7:22","Ephesians 1:11","Hebrews 9:15","Romans 8:9","1 John 5:11\u201313","Hebrews 6:13\u201316","Hebrews 6:17\u201320","Hebrews 7:15\u201322","Jeremiah 31:32","Ephesians 2:8\u20139"],"subsections":[]},{"level":2,"heading":"4. The Kingdom of the New Covenant","bibleReferences":["Colossians 1:18","Luke 22:29"],"subsections":[]},{"level":2,"heading":"5. The People of the New Covenant","bibleReferences":["Romans 8:1","Romans 8:9","Romans 8:14","Romans 8:17","Romans 8:29\u201330","Romans 8:31","Romans 8:33\u201339","Colossians 1:12\u201314"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":[],"subsections":[]}]},{"chapterNumber":13,"title":"Chapter 13: The Mystery of Christ","sections":[{"level":2,"heading":"Introduction","bibleReferences":["2 Timothy 1:9","Titus 1:2","Romans 1:16","Acts 1:6"],"subsections":[]},{"level":2,"heading":"1. The Unity of God's Plan","bibleReferences":["Ephesians 1:9\u201310","Acts 2:38\u201339","Colossians 1:25\u201328","Colossians 2:4\u201323","Ephesians 3:1\u20136","1 Peter 1:10\u201312"],"subsections":[]},{"level":2,"heading":"2. Israel, Christ, and the Church","bibleReferences":["Acts 28:23","Acts 19:8\u20139"],"subsections":[]},{"level":2,"heading":"a. Israel","bibleReferences":["Romans 11:1","Romans 4:1","2 Corinthians 11:22","Acts 3:25\u201326","Romans 9:3\u20135","Ephesians 2:12","Romans 10:4","Romans 4:9\u201317","Romans 4:11","John 8:37","John 8:39","Romans 9:8","Romans 4:12","Galatians 3:7","Galatians 3:16\u201317","Galatians 3:15","Galatians 3:19\u201322","Galatians 4:21\u201331","2 Corinthians 3:14\u201316","Romans 3:1\u20134","Matthew 20:1\u201316","John 1:11"],"subsections":[]},{"level":2,"heading":"b. The Christ","bibleReferences":["Matthew 1:1","Romans 1:16","Romans 11:1","Romans 4:1","2 Corinthians 11:22","Romans 11:1\u201310","Romans 11:23"],"subsections":[]},{"level":2,"heading":"c. The Church","bibleReferences":["Psalm 118:22\u201323","Ephesians 2:19\u201322","1 Peter 2:4\u201310","John 1:12\u201313","Philippians 3:3","Colossians 1:18","Galatians 3:26\u201328","Romans 11:16\u201324","Galatians 6:16","2 Corinthians 5:16\u201317","Galatians 3:24","Hebrews 8:13"],"subsections":[]},{"level":2,"heading":"3. The Continuity of the Law and the Gospel","bibleReferences":["John 8:56","Romans 4:6\u20138","1 Corinthians 10:1\u20134","Galatians 3:8","Hebrews 9:25\u201326","Psalm 32:1","Romans 4:7\u20138","Matthew 5:20\u201324","Romans 2:14\u201315","Romans 13:8\u201310","1 John 5:1\u20133","Jeremiah 31:33"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":["Colossians 4:3\u20134","Romans 11:33\u201336"],"subsections":[]}]},{"chapterNumber":14,"title":"Chapter 14: The Eschatological Nature of the Kingdom","sections":[{"level":2,"heading":"Introduction","bibleReferences":[],"subsections":[]},{"level":2,"heading":"1. The Kingdom Inaugurated","bibleReferences":["Romans 10:14\u201315","2 Corinthians 5:20","Revelation 2:5","Romans 8:9","John 3:3"],"subsections":[]},{"level":2,"heading":"2. The Keys of the Kingdom","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. Joining the kingdom through the covenant","bibleReferences":["1 Peter 4:3","Romans 10:9","Hebrews 9:15"],"subsections":[]},{"level":2,"heading":"b. Guarding the kingdom through the covenant","bibleReferences":["1 John 1:10","Hebrews 12:14","John 3:18"],"subsections":[]},{"level":2,"heading":"c. Traitors of the kingdom","bibleReferences":["1 John 2:19","Acts 8:13","2 Peter 2:1","Hebrews 6:4\u20136","Psalm 50:16"],"subsections":[]},{"level":2,"heading":"3. The Sacraments of the Kingdom","bibleReferences":[],"subsections":[]},{"level":2,"heading":"a. Baptism","bibleReferences":["Romans 6:3\u20135","1 Peter 3:21\u201322","1 Corinthians 5:11"],"subsections":[]},{"level":2,"heading":"b. The Lord's Supper","bibleReferences":["Hebrews 10:23\u201325"],"subsections":[]},{"level":2,"heading":"4. The Kingdom Consummated","bibleReferences":["Acts 17:31","Acts 17:30","Psalm 2:12","2 Peter 3:15","2 Thessalonians 1:4\u201310","Hebrews 9:27\u201328","Matthew 25:31\u201346","Revelation 20:15","1 Corinthians 15:24","Revelation 21:1\u20137","Revelation 21:12","Revelation 21:26","Revelation 22:2","Revelation 21:23","Revelation 5:9\u201310","Revelation 21:3\u20134","Revelation 22:4","Revelation 22:16\u201318"],"subsections":[]},{"level":2,"heading":"Conclusion","bibleReferences":["Romans 9:5"],"subsections":[]}]},{"chapterNumber":15,"title":"Conclusion","sections":[{"level":1,"heading":"Conclusion","bibleReferences":["Romans 8:32","Hebrews 6:19","Romans 10:11\u201313","Ephesians 3:14\u201321"],"subsections":[]}]}]}

